                    }}
                  >
                    <span
                      className="inline-block w-3 h-3 rounded border"
                      style={{
                        backgroundColor: includeMerged
                          ? (colors.accent?.violet?.[500] || "#8B5CF6")
                          : "transparent",
                        borderColor: includeMerged
                          ? (colors.accent?.violet?.[500] || "#8B5CF6")
                          : colors.border,
                      }}
                      aria-hidden="true"
                    />
                    Show merged
