                      className="inline-block w-3 h-3 rounded border"
                      style={{
                        backgroundColor: candidateFilterActive
                          ? (colors.accent?.amber?.[500] || "#F59E0B")
                          : "transparent",
                        borderColor: candidateFilterActive
                          ? (colors.accent?.amber?.[500] || "#F59E0B")
                          : colors.border,
