                        fontWeight: 600,
                      }}
                    >
                      ({candidateGroupsCount})
                    </span>
                  </button>
                ) : null}
              </div>
            ) : null}
          </div>
        </div>
          {cities.length ? (
            <NavyFilterBar.Select
