          sonnerToast.success(
            `Merged ${N} customer${N === 1 ? "" : "s"} into ${res?.primary_name || "primary"}.`,
            { description: `${totalRewired.toLocaleString()} related record${totalRewired === 1 ? "" : "s"} reassigned.` },
          );
          load();
          loadCounts();
          loadCandidates();
