        />
      ) : null}
      {confirmDeleteOpen && _pendingDeleteCount >= _CATASTROPHIC_THRESHOLD ? (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center px-4"
          style={{ background: "rgba(15,23,42,0.55)" }}
